import{_ as e,c as t,o as a,a4 as i}from"./chunks/framework.ttppV29E.js";const g=JSON.parse('{"title":"Escaping Mapped Values","description":"","frontmatter":{},"headers":[],"relativePath":"docs/workflows/escaping.md","filePath":"docs/workflows/escaping.md","lastUpdated":1795163079000}'),s={name:"docs/workflows/escaping.md"},n=i('<h1 id="escaping-mapped-values" tabindex="-1">Escaping Mapped Values <a class="header-anchor" href="#escaping-mapped-values" aria-label="Permalink to &quot;Escaping Mapped Values&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p>Auto Escaping will be released in version 2.42.0, planned for release on 21/10/2026.</p></div><p>Special characters in a value mapped with <a href="./mapping.html#liquid">Liquid</a> can break the document it&#39;s mapped into. For example, a quote or line break breaks JSON, and a <code>&amp;</code> or <code>&lt;</code> breaks XML. With <strong>auto escaping</strong> turned on, AireFlow escapes each mapped value to suit its destination, so you don&#39;t need hand-written <code>replace</code> filters.</p><h2 id="turning-on-auto-escaping" tabindex="-1">Turning on auto escaping <a class="header-anchor" href="#turning-on-auto-escaping" aria-label="Permalink to &quot;Turning on auto escaping&quot;">​</a></h2><p>Auto escaping is set per task, with the <strong>Auto Escape Mappings</strong> switch in the task&#39;s properties. We recommend turning it on wherever possible.</p><ul><li>New tasks created in the designer have it turned on.</li><li>Existing tasks have it turned off and keep working as before until you turn it on.</li><li>Once turned on and saved, it can&#39;t be turned off again in the designer.</li></ul><p>The setting is kept when you <a href="./import-export.html">export and import</a> a workflow definition or create a new version. For definitions <a href="./git-import.html">imported from a Git repository</a>, add <code>&quot;AutoEscape&quot;: true</code> to each task in the repository, or enable it in your dev environment and re-export the definition.</p><h2 id="which-fields-are-escaped" tabindex="-1">Which fields are escaped <a class="header-anchor" href="#which-fields-are-escaped" aria-label="Permalink to &quot;Which fields are escaped&quot;">​</a></h2><table><thead><tr><th>Field</th><th>Escaping</th><th>Output for <code>Tom &amp; &quot;TJ&quot; &lt;Jerry&gt;</code></th></tr></thead><tbody><tr><td>HTTP task body with a JSON Content-Type, and <a href="./mutations.html">mutations</a></td><td>JSON</td><td><code>Tom \\u0026 \\u0022TJ\\u0022 \\u003CJerry\\u003E</code></td></tr><tr><td>HTTP task body with an XML or HTML Content-Type, and emitted contexts (the <strong>Output Context</strong> field)</td><td>XML/HTML</td><td><code>Tom &amp;amp; &amp;quot;TJ&amp;quot; &amp;lt;Jerry&amp;gt;</code></td></tr><tr><td>Everything else, including the HTTP task URL and headers, email fields and other Content-Types</td><td>None</td><td><code>Tom &amp; &quot;TJ&quot; &lt;Jerry&gt;</code></td></tr></tbody></table><ul><li>Only the output of Liquid expressions (<code>{{ ... }}</code>) is escaped, not the text around them. XPath expressions aren&#39;t affected.</li><li>Non-ASCII characters are escaped too. For example, <code>Zürich</code> becomes <code>Z\\u00FCrich</code> in JSON and <code>Z&amp;#xFC;rich</code> in XML. Parsers read these back as the original value.</li><li>When the Content-Type is JSON and the mapped body starts with <code>{</code> or <code>[</code>, the body must be valid JSON, or the task fails with <code>HTTP body is not valid JSON after mapping</code>.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="json-http-body" tabindex="-1">JSON HTTP body <a class="header-anchor" href="#json-http-body" aria-label="Permalink to &quot;JSON HTTP body&quot;">​</a></h3><p>Given a context where <code>name</code> is <code>Tom &amp; Jerry &quot;TJ&quot;</code> and <code>notes</code> spans two lines, this body:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ &quot;name&quot;: &quot;{{ context.name }}&quot;, &quot;notes&quot;: &quot;{{ context.notes }}&quot; }</span></span></code></pre></div><p>produces valid JSON:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code>{ &quot;name&quot;: &quot;Tom \\u0026 Jerry \\u0022TJ\\u0022&quot;, &quot;notes&quot;: &quot;line one\\nline two&quot; }</code></pre></div><p>Mutations are escaped the same way, so free text containing quotes, backslashes or line breaks can&#39;t produce an invalid patch document.</p><h3 id="xml-elements" tabindex="-1">XML elements <a class="header-anchor" href="#xml-elements" aria-label="Permalink to &quot;XML elements&quot;">​</a></h3><p>An expression that refers to an element with child elements, such as <code>{{ context }}</code>, is inserted into XML and HTML output as markup rather than escaped text. Given a <code>person</code> element containing <code>first</code> and <code>last</code> elements:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{{ context.person }}&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;form&lt;/</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>produces:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">first</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Ann&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">first</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">last</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Lee </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&amp;amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Co&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">last</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;form&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="line-breaks-in-html" tabindex="-1">Line breaks in HTML <a class="header-anchor" href="#line-breaks-in-html" aria-label="Permalink to &quot;Line breaks in HTML&quot;">​</a></h3><p><code>newline_to_br</code> escapes each line, then joins them with <code>&lt;br /&gt;</code>:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{{ context.notes | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">newline_to_br</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>produces <code>&lt;p&gt;line one&lt;br /&gt;line &amp;lt;two&amp;gt;&lt;/p&gt;</code>.</p><h3 id="http-task-url" tabindex="-1">HTTP task URL <a class="header-anchor" href="#http-task-url" aria-label="Permalink to &quot;HTTP task URL&quot;">​</a></h3><p>The URL isn&#39;t escaped automatically. Use <code>url_encode</code> on values in a query string or path:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://example.com/api/search?q={{ context.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">search</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">url_encode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>For <code>a b&amp;c</code>, this produces <code>https://example.com/api/search?q=a+b%26c</code>.</p><h2 id="turning-escaping-off-with-raw" tabindex="-1">Turning escaping off with <code>raw</code> <a class="header-anchor" href="#turning-escaping-off-with-raw" aria-label="Permalink to &quot;Turning escaping off with `raw`&quot;">​</a></h2><p>To insert a value exactly as it is, such as a JSON object held in the context, use the <code>raw</code> filter:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;value&quot;: {{ updateContext.detailsJson | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">raw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Only use <code>raw</code> for values you trust to be valid in that position. Otherwise, quotes or <code>&lt;</code> in the value can break the output or inject extra fields.</p></div><h2 id="previews" tabindex="-1">Previews <a class="header-anchor" href="#previews" aria-label="Permalink to &quot;Previews&quot;">​</a></h2><p>The expression previews for HTTP task bodies and mutations show the escaped output. Emitted contexts don&#39;t have a preview.</p><h2 id="moving-an-existing-task-to-auto-escaping" tabindex="-1">Moving an existing task to auto escaping <a class="header-anchor" href="#moving-an-existing-task-to-auto-escaping" aria-label="Permalink to &quot;Moving an existing task to auto escaping&quot;">​</a></h2><p>Auto escaping doesn&#39;t remove hand-written escaping, so any left in place escapes values twice. For example, <code>| escape</code> would turn <code>&lt;</code> into <code>&amp;amp;lt;</code>.</p><ol><li><p><a href="./import-export.html#exporting">Export the workflow definition</a> to keep a copy. Consider making the change in a <a href="./versioning.html#creating-a-new-version">new version</a>, because the setting applies to each version&#39;s copy of the task separately.</p></li><li><p>Remove manual escaping from the task&#39;s HTTP body, emitted context and mutations, such as:</p><ul><li><code>| escape</code></li><li><code>| replace: &#39;&amp;&#39;, &#39;&amp;amp;&#39;</code> and similar <code>replace</code> filters for <code>&lt;</code> and <code>&gt;</code></li><li><code>| replace: &#39;&quot;&#39;, &#39;\\&quot;&#39;</code> and other <code>replace</code> filters that escape quotes, backslashes or newlines for JSON</li><li>the <code>{% capture newline %}</code> workaround</li></ul><p>Keep any <code>url_encode</code> filters in the URL.</p></li><li><p>Turn on <strong>Auto Escape Mappings</strong>, check the previews, then save. Once saved, it can&#39;t be turned off again in the designer.</p></li></ol>',39),o=[n];function l(d,p,h,r,c,u){return a(),t("div",null,o)}const m=e(s,[["render",l]]);export{g as __pageData,m as default};
